begin;
create extension if not exists pgtap with schema extensions;grant usage on schema extensions to cuevo_api;set local search_path=extensions,pg_catalog;select plan(14);
insert into app.courses(school_id,id,class_id,subject_id,created_by,title,description,status)values('10000000-0000-4000-8000-000000000001','99300000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','43000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Class evidence fixture','Synthetic','PUBLISHED');
insert into app.assessments(school_id,id,course_id,created_by,title,instructions,max_score,academic_reference_id)select'10000000-0000-4000-8000-000000000001',('99310000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'99300000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Class source '||i,'School authored',10,'61000000-0000-4000-8000-000000000001'from generate_series(1,2)i;
create temporary table class_summary_sources(numeric_id uuid,rubric_id uuid);grant select,insert,update on class_summary_sources to cuevo_api;
set local role cuevo_api;select set_config('app.school_id','10000000-0000-4000-8000-000000000001',true);select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
do $$declare rubric uuid;submission uuid;begin
 rubric:=internal.create_rubric('99300000-0000-4000-8000-000000000001','Class native rubric','school-class-1','[{"key":"explanation","title":"Explanation","levels":[{"key":"shown","label":"Shown","description":"Explain the school example."}]}]');perform internal.configure_assessment_rubric('99310000-0000-4000-8000-000000000002',rubric,1);
 perform set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);submission:=internal.create_learning_submission('99310000-0000-4000-8000-000000000001','Class numeric source');perform set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);insert into class_summary_sources(numeric_id)values(internal.release_marking(internal.mark_submission(submission,0,'Released native zero',1,0,true),1,true));
 perform set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);submission:=internal.create_learning_submission('99310000-0000-4000-8000-000000000002','Class rubric source');perform set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);update class_summary_sources set rubric_id=internal.release_rubric_marking(internal.mark_rubric_submission(submission,rubric,'[{"criterionKey":"explanation","levelKey":"shown"}]','Human released criterion',2,0,true),1,true);
end$$;
select lives_ok($$select internal.read_class_learning_summary('30000000-0000-4000-8000-000000000001',100,null)$$,'current assigned teacher reads bounded source class page');
select ok(exists(select 1 from jsonb_array_elements(internal.read_class_learning_summary('30000000-0000-4000-8000-000000000001',100,null)->'items')item,jsonb_array_elements(item->'academic'->'sources')source where item->>'learnerId'='20000000-0000-4000-8000-000000000012'and source->>'resultId'=(select numeric_id::text from class_summary_sources)and source->'nativeResult'->>'score'='0'),'class summary preserves verified zero numeric source');
select ok(exists(select 1 from jsonb_array_elements(internal.read_class_learning_summary('30000000-0000-4000-8000-000000000001',100,null)->'items')item,jsonb_array_elements(item->'academic'->'sources')source where source->>'resultId'=(select rubric_id::text from class_summary_sources)and source->'nativeResult'->>'type'='rubric'and not(source->'nativeResult'?'score')),'rubric class source preserves descriptors without invented scalar');
select is(internal.read_class_learning_summary('30000000-0000-4000-8000-000000000001',1,null)->>'coverage','NOT_ESTABLISHED','source page never asserts curriculum coverage');
select ok(internal.read_class_learning_summary('30000000-0000-4000-8000-000000000001',1,null)->>'nextCursor'is not null,'class learner page retains sentinel cursor');
select throws_ok($$select internal.read_class_learning_summary('30000000-0000-4000-8000-000000000002',25,null)$$,'42501',null,'teacher cannot read another assigned class');
reset role;
update app.enrollments set status='revoked'where school_id='10000000-0000-4000-8000-000000000001'and class_id='30000000-0000-4000-8000-000000000001'and student_actor_id='20000000-0000-4000-8000-000000000012';
set local role cuevo_api;
select ok(not exists(select 1 from jsonb_array_elements(internal.read_class_learning_summary('30000000-0000-4000-8000-000000000001',100,null)->'items')item where item->>'learnerId'='20000000-0000-4000-8000-000000000012'),'class page excludes revoked learner exact enrollment');
reset role;update app.enrollments set status='active'where school_id='10000000-0000-4000-8000-000000000001'and class_id='30000000-0000-4000-8000-000000000001'and student_actor_id='20000000-0000-4000-8000-000000000012';
set local role cuevo_api;select set_config('app.actor_id','20000000-0000-4000-8000-000000000002',true);
select lives_ok($$select internal.read_class_learning_summary('30000000-0000-4000-8000-000000000001',100,null)$$,'current coordinator reads class source pattern');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);
select throws_ok($$select internal.read_class_learning_summary('30000000-0000-4000-8000-000000000001',25,null)$$,'42501',null,'student cannot enumerate class evidence');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000072',true);
select throws_ok($$select internal.read_class_learning_summary('30000000-0000-4000-8000-000000000001',25,null)$$,'42501',null,'parent cannot enumerate class evidence');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);select set_config('app.school_id','10000000-0000-4000-8000-000000000002',true);
select throws_ok($$select internal.read_class_learning_summary('30000000-0000-4000-8000-000000000001',25,null)$$,'42501',null,'foreign tenant selector cannot authorize class evidence');
reset role;
select ok(not has_function_privilege('authenticated','internal.read_class_learning_summary(uuid,integer,uuid)','EXECUTE')and not has_function_privilege('cuevo_worker','internal.read_class_learning_summary(uuid,integer,uuid)','EXECUTE'),'class summary exposes no browser or worker grant');
insert into app.intelligence_policies(school_id,version,fixture_enabled,approved_by)values('10000000-0000-4000-8000-000000000001',1,true,'20000000-0000-4000-8000-000000000001')on conflict(school_id)do nothing;
create temporary table class_outcome_source(intervention_id uuid);grant select,insert,update on class_outcome_source to cuevo_api;
set local role cuevo_api;select set_config('app.school_id','10000000-0000-4000-8000-000000000001',true);select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
do $$declare proposal uuid;begin proposal:=internal.create_recommendation((select numeric_id from class_summary_sources),'{"observation":"Recorded native zero","interpretation":"Teacher support","recommendation":"Try practice","rationale":"Source evidence","uncertainty":"Observed source only","activityTitle":"Class support source","instructions":"Practise the school example"}');perform internal.decide_recommendation(proposal,'APPROVE','Teacher approved source',null,null);insert into class_outcome_source select id from app.interventions where school_id='10000000-0000-4000-8000-000000000001'and recommendation_id=proposal;end$$;
reset role;
update app.interventions set follow_up_assessment_id='99310000-0000-4000-8000-000000000002'where id=(select intervention_id from class_outcome_source);
set local role cuevo_api;select set_config('app.actor_id','20000000-0000-4000-8000-000000000002',true);
select ok(exists(select 1 from jsonb_array_elements(internal.read_class_learning_summary('30000000-0000-4000-8000-000000000001',100,null)->'items')item,jsonb_array_elements_text(item->'support'->'interventionIds')source where source=(select intervention_id::text from class_outcome_source)),'same-class linked source remains in support summary');
reset role;insert into app.courses(school_id,id,class_id,subject_id,created_by,title,description,status)values('10000000-0000-4000-8000-000000000001','99300000-0000-4000-8000-000000000002','30000000-0000-4000-8000-000000000002','43000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','Different class reassessment','Synthetic','PUBLISHED');
insert into app.assessments(school_id,id,course_id,created_by,title,instructions,max_score,academic_reference_id)values('10000000-0000-4000-8000-000000000001','99310000-0000-4000-8000-000000000003','99300000-0000-4000-8000-000000000002','20000000-0000-4000-8000-000000000001','Foreign class source','School authored',10,'61000000-0000-4000-8000-000000000001');
update app.interventions set follow_up_assessment_id='99310000-0000-4000-8000-000000000003'where id=(select intervention_id from class_outcome_source);
set local role cuevo_api;select set_config('app.actor_id','20000000-0000-4000-8000-000000000002',true);
select ok(not exists(select 1 from jsonb_array_elements(internal.read_class_learning_summary('30000000-0000-4000-8000-000000000001',100,null)->'items')item,jsonb_array_elements_text(item->'support'->'interventionIds')source where source=(select intervention_id::text from class_outcome_source)),'another class linked reassessment cannot leak through same baseline summary');
reset role;
select*from finish();rollback;
